class LoadAsymmetricTensorField(RootNode):

    def __init__(self, load_path : str, A_array_name : str, B_array_name : str, C_array_name : str, D_array_name : str):
        """
        Loads a 2x2 asymmetric tensor field from a file given at load_path.

        Args:
            load_path: The path to the vector field that should be loaded.
            A_array_name: The name of the array storing the (1,1) component of the tensors.
            B_array_name: The name of the array storing the (1,2) component of the tensors.
            C_array_name: The name of the array storing the (2,1) component of the tensors.
            D_array_name: The name of the array storing the (2,2) component of the tensors.
        """

        super().__init__(load_path, AsymmetricTensor, locals(), [A_array_name, B_array_name, C_array_name, D_array_name])

        reader = vtk.vtkXMLImageDataReader()
        reader.SetFileName(self.check_file)
        reader.Update()

        image = reader.GetOutput()
        pd = image.GetPointData()
        numArrays = pd.GetNumberOfArrays()

        if correctness_checks_on():
            if numArrays < 4:
                raise ValueError(f"File {load_path} has only {numArrays} arrays, but needs at least 4 to load an asymmetric tensor field.")

            if not pd.HasArray(A_array_name):
                raise ValueError(f"File {load_path} has no array '{A_array_name}'")

            if not pd.HasArray(B_array_name):
                raise ValueError(f"File {load_path} has no array '{B_array_name}'")

            if not pd.HasArray(C_array_name):
                raise ValueError(f"File {load_path} has no array '{C_array_name}'")

            if not pd.HasArray(D_array_name):
                raise ValueError(f"File {load_path} has no array '{D_array_name}'")

            if len(self.dimensions) > 2 and self.dimensions[2] != 1:
                raise ValueError(f"File {load_path} is three dimensional but currently only 2D symmetric tensor fields are supported.")

        self.A_array_name = A_array_name
        self.B_array_name = B_array_name
        self.C_array_name = C_array_name
        self.D_array_name = D_array_name
        self._commit()

    @classmethod
    def chat_description(cls):
        return "queued loading asymmetric tensor field"
